original_args:
{"command": "mkdir -p /tmp/vbisect && cd /tmp/vbisect && cat > test.mjs <<'EOF'
import { compileScript, parse as parseSFC } from '@vue/compiler-sfc';
const src = `<script setup lang="ts">
type ButtonVariant =
  | { type: "link"; href: string }
  | { type: "button"; onClick: () => void }

defineProps<{
  variant: ButtonVariant
}>()
</script>

<template>
  <div>{{ variant.type }}</div>
</template>`;
const { descriptor } = parseSFC(src, { filename: 'test.vue' });
const result = compileScript(descriptor, { id: 'test.vue', inlineTemplate: true, templateOptions: { compilerOptions: { mode: 'module' } } });
const m = result.content.match(/variant:.*$/m);
console.log(process.argv[2], '=>', m && m[0]);
EOF
for v in 3.5.0 3.5.13 3.5.18 3.5.22 3.6.0-alpha.7 3.6.0-beta.1 3.6.0-beta.5; do
  npm install --silent --no-save @vue/compiler-sfc@$v >/dev/null 2>&1 && PATH=/tmp/node-v22.14.0-linux-x64/bin:$PATH node test.mjs $v
done", "dangerouslyDisableSandbox": true, "description": "Test union-type prop inference across Vue versions", "timeout": 300000}

